// DeepL API for Chinese transcription via local proxy
var DeepLTranscription = {
  cache: {},

  getApiUrl: function () {
    return "/api/deepl/translate";
  },

  getApiKey: function () {
    return typeof Config !== "undefined" && Config.deepl && Config.deepl.apiKey
      ? Config.deepl.apiKey
      : "";
  },

  getTranscription: function (text, sourceLang, targetLang, callback) {
    var cacheKey = sourceLang + "_" + targetLang + "_" + text;
    if (DeepLTranscription.cache[cacheKey]) {
      callback(DeepLTranscription.cache[cacheKey]);
      return;
    }

    var apiKey = DeepLTranscription.getApiKey();
    var apiUrl = DeepLTranscription.getApiUrl();

    if (!apiKey) {
      callback("");
      return;
    }
    $.ajax({
      url: apiUrl,
      method: "POST",
      contentType: "application/json",
      data: JSON.stringify({
        text: text,
        source_lang: sourceLang.toUpperCase(),
        target_lang: targetLang.toUpperCase(),
        auth_key: apiKey,
      }),
      success: function (response) {
        if (response && response.translations && response.translations[0]) {
          var transcription = response.translations[0].text;
          DeepLTranscription.cache[cacheKey] = transcription;
          callback(transcription);
        } else {
          callback("");
        }
      },
      error: function (xhr, status, error) {
        callback("");
      },
    });
  },
};

// Optional audio for the translation revealed after an answer.
var TranslationAudio = {
  enabled: false,
  speech: null,
  recording: null,
  timer: null,
  menuLanguage: function () {
    return BabadumRecordings.normalizeLanguage(InterfaceData.data.lang_code || "us");
  },
  languageTag: function (code) {
    return {us: "en", gb: "en-GB", cn: "zh", jp: "ja", se: "sv", cz: "cs", gr: "el"}[code] || code;
  },
  prepare: function (round) {
    var answer;
    for (var i = 0; i < round.words.length; i++) {
      if (round.words[i].word_key == round.id) { answer = round.words[i]; break; }
    }
    if (!answer) return;
    var menu = this.menuLanguage();
    var sourceCode = round.arabic ? "us" : round.lang || Game.getLangCode(round.lang_key);
    if (!sourceCode) return;
    var source = this.languageTag(sourceCode).split("-")[0].toUpperCase();
    var target = this.languageTag(menu).split("-")[0].toUpperCase();
    round.translationMenuCode = menu;
    round.translationLang = this.languageTag(menu);
    round.translationText = null;
    if (!round.arabic && source == target) return;
    var recording = round.nativeTranslation && round.nativeTranslation.lang == menu ? round.nativeTranslation :
      BabadumLibrary.get(menu, round.id) || BabadumRecordings.get(menu, round.id);
    if (recording) { round.translationText = recording.word; return; }
    if (source == target) { round.translationText = answer.sourceWord || answer.word; return; }
    DeepLTranscription.getTranscription(answer.sourceWord || answer.word, source, target, function (text) {
      if (round.translationMenuCode == menu) round.translationText = text || null;
    });
  },
  setEnabled: function (enabled) {
    this.enabled = enabled;
    try { localStorage.setItem("playTranslation", String(enabled)); } catch (e) {}
    if (!enabled) this.cancel();
    if (typeof Words != "undefined" && typeof Game != "undefined" && Game.langID !== void 0) {
      Words.arr = [];
      Words.get();
    }
  },
  cancel: function () {
    clearTimeout(this.timer);
    if (this.recording) {
      var recording = this.recording;
      this.recording = null;
      recording.unload();
    }
    if (this.speech && window.speechSynthesis) window.speechSynthesis.cancel();
    this.speech = null;
  },
  play: function (round) {
    if (!this.enabled || !Sounds.active || !round.translationText) return;
    if (round.translationMenuCode && round.translationMenuCode != this.menuLanguage()) return;
    this.cancel();
    var entry = round.nativeTranslation && round.nativeTranslation.lang == this.menuLanguage() ? round.nativeTranslation :
      BabadumLibrary.get(this.menuLanguage(), round.id) ||
      BabadumRecordings.get(this.menuLanguage(), round.id) ||
      BabadumRecordings.getByText(this.menuLanguage(), round.translationText);
    if (!entry || !(entry.audioUrls && entry.audioUrls.length || entry.audioUrl) || typeof Howl == "undefined") { this.speak(round); return; }
    round.translationText = entry.word;
    var recording = new Howl({
      src: entry.audioUrls && entry.audioUrls.length ? entry.audioUrls : [entry.audioUrl],
      html5: true,
      rate: Game.speed,
      onend: function () { if (TranslationAudio.recording == recording) TranslationAudio.cancel(); },
      onloaderror: function () {
        if (TranslationAudio.recording != recording) return;
        TranslationAudio.cancel();
        TranslationAudio.speak(round);
      },
      onplayerror: function () {
        if (TranslationAudio.recording != recording) return;
        TranslationAudio.cancel();
        TranslationAudio.speak(round);
      },
    });
    this.recording = recording;
    this.timer = setTimeout(function () { TranslationAudio.cancel(); }, 20000);
    recording.play();
  },
  speak: function (round) {
    if (!window.speechSynthesis || !window.SpeechSynthesisUtterance) return;
    var speech = new SpeechSynthesisUtterance(round.translationText);
    var lang = (round.translationLang || "en").toLowerCase();
    speech.lang = lang;
    var voices = window.speechSynthesis.getVoices();
    for (var i = 0; i < voices.length; i++) {
      if (voices[i].lang.toLowerCase().split("-")[0] == lang.split("-")[0]) {
        speech.voice = voices[i];
        break;
      }
    }
    speech.onend = speech.onerror = function () {
      if (TranslationAudio.speech == speech) {
        clearTimeout(TranslationAudio.timer);
        TranslationAudio.speech = null;
      }
    };
    this.speech = speech;
    this.timer = setTimeout(function () { TranslationAudio.cancel(); }, 10000);
    window.speechSynthesis.speak(speech);
  },
};
try { TranslationAudio.enabled = localStorage.getItem("playTranslation") === "true"; } catch (e) {}

// HanziWriter integration for Chinese characters
var HanziWriterManager = {
  current: null,
  isAnimating: false,

  // Shared config for HanziWriter
  getConfig: function () {
    return {
      width: 180,
      height: 180,
      padding: 5,
      strokeColor: "#fff",
      radicalColor: "#fff",
      showOutline: false,
      strokeAnimationSpeed: 2,
      delayBetweenStrokes: 200,
      showCharacter: false,
    };
  },

  create: function (character, wordData) {
    // Remove old writer if exists
    if (HanziWriterManager.current) {
      $(HanziWriterManager.current.target).empty();
      HanziWriterManager.current = null;
    }

    var writerContainer = $('<div class="hanzi-writer-container"></div>');
    var writerDiv = $('<div class="hanzi-writer"></div>');

    writerContainer.append(writerDiv);

    // Create HanziWriter instance for each character
    var writers = [];
    for (var i = 0; i < character.length; i++) {
      var charDiv = $('<div class="hanzi-char"></div>');
      writerDiv.append(charDiv);

      if (typeof HanziWriter !== "undefined") {
        var localConfig = HanziWriterManager.getConfig();
        (function (target, config) {
          config.charDataLoader = function (char, onComplete, onError) {
            $.getJSON("data/hanzi/" + encodeURIComponent(char) + ".json")
              .done(onComplete)
              .fail(function () {
                target.data("strokeUnavailable", true).empty().text(char).css({
                  cursor: "default", fontSize: "100px", lineHeight: "180px"
                });
                onError();
              });
          };
        })(charDiv, localConfig);
        var writer = HanziWriter.create(
          charDiv[0],
          character[i],
          localConfig,
        );
        writers.push(writer);

        // Add click handler for individual character
        (function (w, idx) {
          $(charDiv).css("cursor", "pointer");
          $(charDiv).on("click", function (e) {
            e.preventDefault();
            e.stopPropagation();
            if ($(this).data("strokeUnavailable")) return;
            w.hideCharacter();
            setTimeout(function () {
              w.animateCharacter();
            }, 100);
            if (wordData && wordData.sound && !wordData.sound.fake) {
              wordData.sound.play();
            }
          });
        })(writer, i);
      }
    }

    // Animate all characters one by one, chaining them
    var animateAll = function () {
      var animateNext = function (index) {
        if (index >= writers.length) return;

        writers[index].animateCharacter({
          onComplete: function () {
            animateNext(index + 1);
          },
        });
      };

      animateNext(0);
    };

    // Auto-play on load
    setTimeout(animateAll, 500);

    // Make transcription clickable to play audio only
    var transcriptionClickHandler = function (e) {
      e.preventDefault();
      e.stopPropagation();

      // Only play sound, don't re-render
      if (wordData && wordData.sound && !wordData.sound.fake) {
        wordData.sound.play();
      }
      return false;
    };

    HanziWriterManager.current = {
      target: writerContainer[0],
      writers: writers,
      animateAll: animateAll,
      transcriptionClickHandler: transcriptionClickHandler,
    };

    return writerContainer;
  },

  clear: function () {
    if (HanziWriterManager.current && HanziWriterManager.current.writers) {
      HanziWriterManager.current.writers.forEach(function (writer) {
        writer.hideCharacter();
      });
    }
    $(".transcription-text").remove();
    $(".word-container").remove();
    $(".hanzi-writer-container").remove();
  },
};

// Pinyin helper
var PinyinHelper = {
  getPinyin: function (text) {
    if (typeof pinyinPro !== "undefined" && pinyinPro.pinyin) {
      return pinyinPro.pinyin(text, { toneType: "symbol" });
    }
    return "";
  },
};

